import React from 'react';
import Header from './Clients/Widgets/Header/Header';
import Footer from './Clients/Widgets/Footer/Footer';

const ClientLayout = ({ children, isAuthenticated, onLogout, currentUser }) => {
  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-br from-white via-white to-neutral-50 dark:from-neutral-950 dark:via-neutral-950 dark:to-neutral-900">
      <Navbar isAuthenticated={isAuthenticated} onLogout={onLogout} />

      <main className="flex-grow">
        {children}
      </main>

      <Footer 
        currentUser={currentUser} 
        isAuthenticated={isAuthenticated}
        onLogout={onLogout}
      />
    </div>
  );
};

export default ClientLayout;
